 *   fresh workdir, no api/frontend/canary-e2e node_modules).
 * @example WORKSPACE_PACKAGES => ["api", "frontend", "canary-e2e"]
 ***/
export const WORKSPACE_PACKAGES = ["api", "frontend", "canary-e2e"];

/***
